 import React, { useState, useEffect } from 'react'
import { useParams, useNavigate, Link } from 'react-router-dom'
import { supabase } from '../lib/supabase'
import { useAuth } from '../contexts/AuthContext'
import { useToast } from '../contexts/ToastContext'
import VerifiedBadge from '../components/VerifiedBadge'
import { initiatePayment } from '../services/paymentService'

export default function CommunityDetail() {
    const { id } = useParams()
    const { user, profile } = useAuth()
    const { showToast } = useToast()
    const navigate = useNavigate()
    const [community, setCommunity] = useState(null)
    const [posts, setPosts] = useState([])
    const [isMember, setIsMember] = useState(false)
    const [isCreator, setIsCreator] = useState(false)
    const [loading, setLoading] = useState(true)
    const [showPaymentModal, setShowPaymentModal] = useState(false)
    const [newPost, setNewPost] = useState('')
    const [submitting, setSubmitting] = useState(false)
    const [showPredictionModal, setShowPredictionModal] = useState(false)
    const [predictionData, setPredictionData] = useState({
        result: 'Draw',
        yellowCards: 2,
        redCards: 0,
        corners: 5,
        offsides: 1
    })

    useEffect(() => {
        loadCommunityData()
    }, [id, user])

    const loadCommunityData = async () => {
        setLoading(true)
        try {
            const { data: communityData } = await supabase
                .from('communities')
                .select('*, profiles:creator_id (id, username, full_name, avatar_url, is_verified)')
                .eq('id', id)
                .single()

            setCommunity(communityData)
            setIsCreator(user?.id === communityData?.creator_id)

            if (user) {
                const { data: memberData } = await supabase
                    .from('community_members')
                    .select('*')
                    .eq('community_id', id)
                    .eq('user_id', user.id)
                    .eq('status', 'active')
                    .maybeSingle()
                setIsMember(!!memberData)
            }

            const { data: postsData } = await supabase
                .from('community_posts')
                .select('*, profiles:user_id (id, username, full_name, avatar_url, is_verified)')
                .eq('community_id', id)
                .order('created_at', { ascending: false })

            setPosts(postsData || [])

            const { count } = await supabase
                .from('community_members')
                .select('*', { count: 'exact', head: true })
                .eq('community_id', id)
                .eq('status', 'active')

            if (communityData) {
                setCommunity({ ...communityData, member_count: count || 0 })
            }

        } catch (error) {
            console.error('Error loading community:', error)
            showToast('Failed to load community data', 'error')
        } finally {
            setLoading(false)
        }
    }

    const handleJoin = () => {
        if (!user) {
            showToast('Please sign in to join this community', 'warning')
            navigate('/login')
            return
        }
        setShowPaymentModal(true)
    }

    const handlePayment = async () => {
        if (!user) {
            showToast('Please sign in first', 'error')
            return
        }

        setSubmitting(true)
        try {
            // Check if user has a profile
            const { data: profileData } = await supabase
                .from('profiles')
                .select('id')
                .eq('id', user.id)
                .maybeSingle()

            if (!profileData) {
                await supabase
                    .from('profiles')
                    .insert({
                        id: user.id,
                        username: user.email?.split('@')[0] || 'user',
                        full_name: user.email?.split('@')[0] || 'user'
                    })
            }

            // Check if already a member
            const { data: existingMember } = await supabase
                .from('community_members')
                .select('*')
                .eq('community_id', id)
                .eq('user_id', user.id)
                .maybeSingle()

            if (existingMember) {
                setShowPaymentModal(false)
                setIsMember(true)
                showToast('You are already a member!', 'info')
                return
            }

            // Use community price and payment type
            const amount = community.price || 50.00
            const paymentType = community.payment_type || 'monthly'
            const itemName = `${community.name} - ${paymentType === 'monthly' ? 'Monthly' : 'One-time'} Subscription`

            // Initiate payment (mock or real)
            const result = await initiatePayment(
                id,
                user.id,
                amount,
                itemName
            )

            if (!result.success) {
                throw new Error(result.error)
            }

            // ✅ If mock payment, it's already completed
            if (result.mock) {
                setShowPaymentModal(false)
                setIsMember(true)
                showToast(`✅ Successfully joined the community! (Mock Payment - R${amount})`, 'success')
                await loadCommunityData()
                return
            }

            // 🔴 Real PayFast - redirect to payment gateway
            const form = document.createElement('form')
            form.method = 'POST'
            form.action = result.payfastUrl
            
            Object.entries(result.payfastData).forEach(([key, value]) => {
                const input = document.createElement('input')
                input.type = 'hidden'
                input.name = key
                input.value = value
                form.appendChild(input)
            })
            
            document.body.appendChild(form)
            form.submit()
            
        } catch (error) {
            console.error('Payment error:', error)
            showToast('Failed to process payment: ' + error.message, 'error')
        } finally {
            setSubmitting(false)
        }
    }

    const handleCreatePost = async (e) => {
        e.preventDefault()
        if (!newPost.trim()) {
            showToast('Please write something', 'warning')
            return
        }
        if (!isCreator) {
            showToast('Only the community creator can post in this community', 'error')
            return
        }

        setSubmitting(true)
        try {
            const postData = {
                community_id: id,
                user_id: user.id,
                text: newPost.trim()
            }

            if (predictionData.result) {
                postData.prediction_data = predictionData
            }

            const { data, error } = await supabase
                .from('community_posts')
                .insert(postData)
                .select()
                .single()

            if (error) throw error

            const { data: communityData } = await supabase
                .from('communities')
                .select('post_count')
                .eq('id', id)
                .single()

            await supabase
                .from('communities')
                .update({ post_count: (communityData?.post_count || 0) + 1 })
                .eq('id', id)

            setNewPost('')
            setPredictionData({
                result: 'Draw',
                yellowCards: 2,
                redCards: 0,
                corners: 5,
                offsides: 1
            })
            await loadCommunityData()
            showToast('✅ Post created successfully!', 'success')
        } catch (error) {
            console.error('Error creating post:', error)
            showToast('Failed to create post: ' + error.message, 'error')
        } finally {
            setSubmitting(false)
        }
    }

    const handleLike = async (postId) => {
        if (!user) {
            showToast('Please sign in to like posts', 'warning')
            return
        }

        try {
            const { data: existing } = await supabase
                .from('community_post_likes')
                .select('*')
                .eq('post_id', postId)
                .eq('user_id', user.id)
                .maybeSingle()

            const { data: postData } = await supabase
                .from('community_posts')
                .select('likes_count')
                .eq('id', postId)
                .single()

            const currentLikes = postData?.likes_count || 0

            if (existing) {
                await supabase
                    .from('community_post_likes')
                    .delete()
                    .eq('post_id', postId)
                    .eq('user_id', user.id)

                await supabase
                    .from('community_posts')
                    .update({ likes_count: Math.max(0, currentLikes - 1) })
                    .eq('id', postId)
            } else {
                await supabase
                    .from('community_post_likes')
                    .insert({ post_id: postId, user_id: user.id })

                await supabase
                    .from('community_posts')
                    .update({ likes_count: currentLikes + 1 })
                    .eq('id', postId)
            }

            loadCommunityData()
        } catch (error) {
            console.error('Error liking post:', error)
            showToast('Failed to like post. Please try again.', 'error')
        }
    }

    const canPost = isCreator

    if (loading) {
        return <div className="text-center py-12"><div className="text-gray-500">Loading...</div></div>
    }

    if (!community) {
        return (
            <div className="text-center py-12 bg-white rounded-xl shadow-md">
                <div className="text-4xl mb-4">🔍</div>
                <p className="text-gray-500">Community not found</p>
                <Link to="/community" className="text-green-600 hover:underline mt-4 block">← Back to Communities</Link>
            </div>
        )
    }

    return (
        <div>
            <div className="bg-white rounded-xl shadow-md p-6 mb-6">
                <div className="flex items-start justify-between">
                    <div>
                        <div className="flex items-center gap-2">
                            <span className="text-3xl">🏛️</span>
                            <h1 className="text-2xl font-bold text-gray-800">{community.name}</h1>
                            {isCreator && <span className="text-xs bg-yellow-100 text-yellow-800 px-2 py-1 rounded-full">Admin</span>}
                            {isMember && !isCreator && <span className="text-xs bg-green-100 text-green-800 px-2 py-1 rounded-full">✓ Member</span>}
                        </div>
                        <p className="text-gray-500 mt-1">{community.description || 'A private community for football predictions'}</p>
                        <div className="flex items-center gap-4 mt-3 text-sm text-gray-400">
                            <span>👥 {community.member_count || 0} members</span>
                            <span>📝 {community.post_count || 0} posts</span>
                            <span>💰 R{community.price || 50} {community.payment_type === 'monthly' ? '/month' : 'once'}</span>
                        </div>
                        {isCreator && (
                            <div className="mt-2 text-sm text-green-600">
                                💰 You earn 50% per {community.payment_type === 'monthly' ? 'month' : 'payment'} (R{((community.price || 50) * 0.5).toFixed(2)})
                            </div>
                        )}
                    </div>
                    <div>
                        {isCreator ? (
                            <span className="text-sm bg-yellow-100 text-yellow-800 px-4 py-2 rounded-lg">Creator</span>
                        ) : isMember ? (
                            <span className="text-sm bg-green-100 text-green-800 px-4 py-2 rounded-lg">✓ Member</span>
                        ) : (
                            <button onClick={handleJoin} className="bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 transition font-medium">
                                Join {community.payment_type === 'monthly' ? 'R' + (community.price || 50) + '/month' : 'R' + (community.price || 50) + ' once'}
                            </button>
                        )}
                    </div>
                </div>
            </div>

            {canPost ? (
                <>
                    <div className="bg-white rounded-xl shadow-md p-4 mb-6">
                        <form onSubmit={handleCreatePost} className="flex gap-3">
                            <input type="text" value={newPost} onChange={(e) => setNewPost(e.target.value)} placeholder="📢 Share your community announcement..." className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500" />
                            <button type="button" onClick={() => setShowPredictionModal(true)} className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition">📊 Add Prediction</button>
                            <button type="submit" disabled={submitting || !newPost.trim()} className="bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 transition disabled:opacity-50">{submitting ? 'Posting...' : 'Post'}</button>
                        </form>
                        <p className="text-xs text-gray-400 mt-2">👑 As the creator, your posts are highlighted</p>
                    </div>

                    {posts.length === 0 ? (
                        <div className="text-center py-12 bg-white rounded-xl shadow-md">
                            <div className="text-4xl mb-4">📝</div>
                            <p className="text-gray-500">No posts yet</p>
                            <p className="text-sm text-gray-400">{isCreator ? 'Be the first to share an announcement!' : 'The creator hasn\'t posted anything yet.'}</p>
                        </div>
                    ) : (
                        <div className="space-y-4">
                            {posts.map((post) => {
                                const isPostCreator = post.user_id === community.creator_id
                                return (
                                    <div key={post.id} className={`bg-white rounded-xl shadow-md p-4 ${isPostCreator ? 'border-2 border-yellow-400' : ''}`}>
                                        <div className="flex items-center gap-3 mb-3">
                                            <div className="w-10 h-10 bg-green-500 rounded-full flex items-center justify-center text-white font-bold">
                                                {post.profiles?.username?.[0]?.toUpperCase() || 'U'}
                                            </div>
                                            <div>
                                                <div className="font-semibold flex items-center gap-1.5">
                                                    {post.profiles?.full_name || post.profiles?.username || 'Unknown'}
                                                    {post.profiles?.is_verified && <VerifiedBadge size="sm" />}
                                                    {isPostCreator && <span className="text-xs bg-yellow-100 text-yellow-800 px-2 py-0.5 rounded-full">👑 Admin</span>}
                                                </div>
                                                <div className="text-xs text-gray-400">@{post.profiles?.username} • {new Date(post.created_at).toLocaleDateString()}</div>
                                            </div>
                                        </div>
                                        <p className="text-gray-800 mb-3">{post.text}</p>
                                        {post.prediction_data && (
                                            <div className="bg-gray-50 rounded-lg p-3 mb-3">
                                                <div className="flex items-center justify-between text-sm">
                                                    <span>📊 {post.prediction_data.result || 'Draw'}</span>
                                                    <span>🟨{post.prediction_data.yellowCards || 0} 🟥{post.prediction_data.redCards || 0}</span>
                                                    <span>🏁{post.prediction_data.corners || 0}</span>
                                                </div>
                                            </div>
                                        )}
                                        <button onClick={() => handleLike(post.id)} className="flex items-center gap-1 text-sm text-gray-400 hover:text-red-500 transition">❤️ {post.likes_count || 0}</button>
                                    </div>
                                )
                            })}
                        </div>
                    )}
                </>
            ) : (
                <div className="text-center py-12 bg-white rounded-xl shadow-md">
                    <div className="text-4xl mb-4">🔒</div>
                    <p className="text-gray-500">This community is private</p>
                    <p className="text-sm text-gray-400">Only the creator can post in this community</p>
                    {!isMember && !isCreator && (
                        <button onClick={handleJoin} className="mt-4 bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 transition">Join Now</button>
                    )}
                    {isMember && !isCreator && <p className="mt-4 text-sm text-green-600">✅ You are a member of this community</p>}
                </div>
            )}

            {/* Payment Modal */}
            {showPaymentModal && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl max-w-md w-full p-6">
                        <h2 className="text-xl font-bold text-gray-800 mb-4">💳 Join {community.name}</h2>
                        
                        <div className="bg-gray-50 rounded-lg p-4 mb-4">
                            <div className="flex justify-between items-center">
                                <span className="text-gray-600">
                                    {community.payment_type === 'monthly' ? 'Monthly subscription' : 'One-time payment'}
                                </span>
                                <span className="font-bold text-xl">R{community.price || 50}</span>
                            </div>
                            <div className="flex justify-between items-center text-sm text-gray-500 mt-2 border-t pt-2">
                                <span>👤 Creator earns</span>
                                <span>R{((community.price || 50) * 0.5).toFixed(2)}</span>
                            </div>
                            <div className="flex justify-between items-center text-sm text-gray-500">
                                <span>🏢 Platform fee</span>
                                <span>R{((community.price || 50) * 0.5).toFixed(2)}</span>
                            </div>
                            <p className="text-xs text-gray-400 mt-2">
                                {community.payment_type === 'monthly' 
                                    ? 'Cancel anytime. You\'ll be charged R' + (community.price || 50) + '/month.' 
                                    : 'One-time payment. No recurring charges.'}
                            </p>
                        </div>

                        <div className="flex gap-3">
                            <button
                                onClick={() => setShowPaymentModal(false)}
                                className="flex-1 bg-gray-200 text-gray-700 py-2 rounded-lg hover:bg-gray-300 transition"
                            >
                                Cancel
                            </button>
                            <button
                                onClick={handlePayment}
                                disabled={submitting}
                                className="flex-1 bg-green-600 text-white py-2 rounded-lg hover:bg-green-700 transition disabled:opacity-50 flex items-center justify-center gap-2"
                            >
                                {submitting ? (
                                    <>
                                        <span className="animate-spin">⏳</span> Processing...
                                    </>
                                ) : (
                                    <>
                                        💳 Pay R{community.price || 50}
                                    </>
                                )}
                            </button>
                        </div>

                        <p className="text-xs text-gray-400 text-center mt-4">
                            You will be redirected to PayFast to complete payment securely.
                        </p>
                    </div>
                </div>
            )}

            {/* Prediction Modal */}
            {showPredictionModal && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl max-w-md w-full p-6 max-h-[90vh] overflow-y-auto">
                        <div className="flex justify-between items-center mb-4">
                            <h3 className="text-xl font-bold text-gray-800">📊 Add Prediction</h3>
                            <button onClick={() => setShowPredictionModal(false)} className="text-gray-400 hover:text-gray-600 text-2xl">×</button>
                        </div>
                        <div className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-2">🏆 Result</label>
                                <div className="grid grid-cols-3 gap-2">
                                    {['Home Win', 'Draw', 'Away Win'].map((result) => (
                                        <button key={result} onClick={() => setPredictionData({...predictionData, result})} className={`px-3 py-2 rounded-lg text-sm font-medium transition ${predictionData.result === result ? 'bg-green-600 text-white' : 'bg-gray-100 text-gray-700 hover:bg-gray-200'}`}>
                                            {result === 'Home Win' ? '🏠 Home' : result === 'Away Win' ? '✈️ Away' : '🤝 Draw'}
                                        </button>
                                    ))}
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-3">
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">🟨 Yellow Cards</label>
                                    <input type="number" min="0" max="10" value={predictionData.yellowCards} onChange={(e) => setPredictionData({...predictionData, yellowCards: parseInt(e.target.value) || 0})} className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500" />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">🟥 Red Cards</label>
                                    <input type="number" min="0" max="5" value={predictionData.redCards} onChange={(e) => setPredictionData({...predictionData, redCards: parseInt(e.target.value) || 0})} className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500" />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">🏁 Corners</label>
                                    <input type="number" min="0" max="20" value={predictionData.corners} onChange={(e) => setPredictionData({...predictionData, corners: parseInt(e.target.value) || 0})} className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500" />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">🚩 Offsides</label>
                                    <input type="number" min="0" max="10" value={predictionData.offsides} onChange={(e) => setPredictionData({...predictionData, offsides: parseInt(e.target.value) || 0})} className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500" />
                                </div>
                            </div>
                            <button onClick={() => { setShowPredictionModal(false); showToast('✅ Prediction added to your post! Submit the post to save it.', 'success') }} className="w-full bg-green-600 text-white py-2 rounded-lg hover:bg-green-700 transition">✅ Add to Post</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    )
}
